package com.bank.recon.service;

import java.util.logging.Logger;

// Compares two keystroke logs where '#' is a backspace, using O(1) extra space.
public class KeystrokeComparator {
    private static final Logger log = Logger.getLogger(KeystrokeComparator.class.getName());

    public boolean sameFinalCode(String a, String b) {
        int i = a.length() - 1;
        int j = b.length() - 1;

        while (i >= 0 || j >= 0) {
            i = nextValidIndex(a, i); // land on next surviving char in a
            j = nextValidIndex(b, j); // land on next surviving char in b

            if (i >= 0 && j >= 0) {
                if (a.charAt(i) != b.charAt(j)) {
                    log.info("Final codes differ.");
                    return false;
                }
            } else if (i >= 0 || j >= 0) {
                // one still has a surviving char, the other is exhausted
                log.info("Final codes differ in length.");
                return false;
            }
            i--;
            j--;
        }
        log.info("Final codes match.");
        return true;
    }

    // Moves the index left past deleted characters; returns a surviving index or -1.
    private int nextValidIndex(String s, int idx) {
        int skip = 0;
        while (idx >= 0) {
            if (s.charAt(idx) == '#') {
                skip++;
                idx--;
            } else if (skip > 0) {
                skip--;   // this character is deleted by a pending backspace
                idx--;
            } else {
                break;    // surviving character
            }
        }
        return idx;
    }
}
