package com.bank.recon;

import com.bank.recon.service.KeystrokeComparator;
import java.util.logging.Logger;

public class KeystrokeDemo {
    private static final Logger log = Logger.getLogger(KeystrokeDemo.class.getName());

    public static void main(String[] args) {
        // Keystroke logs where '#' means backspace.
        String rajeshLog = "ab#c";   // final: "ac"
        String priyaLog  = "ad#c";   // final: "ac"

        KeystrokeComparator comparator = new KeystrokeComparator();
        boolean match = comparator.sameFinalCode(rajeshLog, priyaLog);

        log.info(() -> "Logs '" + rajeshLog + "' vs '" + priyaLog
                + "' produce the same code: " + match);
    }
}
